"""Static scientific plots and standalone native-only playback, no simulation."""
from analyze160 import R,D,read,save
from pathlib import Path
import base64,gzip,html,json,math,statistics
def table(head,rows):return '\n'.join(['|'+'|'.join(head)+'|','|'+'|'.join(['---']*len(head))+'|']+['|'+'|'.join(str(v) for v in row)+'|' for row in rows])+'\n'
def number(x,n=3):return '—' if x is None else f'{x:.{n}f}'
def plots(a):
 import matplotlib;matplotlib.use('Agg')
 import matplotlib.pyplot as plt
 plt.rcParams.update({'font.size':10,'axes.grid':True,'grid.alpha':.2});out=D/'plots';out.mkdir(exist_ok=True)
 fig,axs=plt.subplots(4,1,figsize=(12,11),sharex=True)
 for label in ['exact-rest-speed12','dynamic12-v2','adaptive-v3','ablate-actuator-v2']:
  f=read(D/'forecasts'/f'{label}.json.gz');p=f['Points'];t=[x['Time'] for x in p]
  for ax,values in zip(axs,[[x['Rider']['Speed']*3.6 for x in p],[math.degrees(x['Rider']['SlideRadians']) for x in p],[x['Rider']['AngularVelocity'] for x in p],[math.degrees(x['Steering']) for x in p]]):ax.plot(t,values,lw=1,label=label)
 for ax,ylabel in zip(axs,['speed [km/h]','beta [deg]','body yaw [rad/s]','actual steering [deg]']):ax.set_ylabel(ylabel);ax.set_xlim(0,18);ax.legend(fontsize=8,ncol=2)
 axs[-1].set_xlabel('diagnostic forecast time [s]');fig.tight_layout();fig.savefig(out/'diagnostic-controls.png',dpi=160);plt.close(fig)
 traces=[x['Trace'] for x in read(D/'forecasts/exact-rest-speed12.json.gz')['Actions']];t=[x['Time'] for x in traces]
 fig,axs=plt.subplots(3,1,figsize=(12,8),sharex=True)
 axs[0].plot(t,[q['DesiredAlpha'] for q in traces],label='requested alpha');axs[0].plot(t,[q['Imagined']['YawAcceleration'] for q in traces],label='158 assumes steering achieved');axs[0].plot(t,[q['Actual']['YawAcceleration'] for q in traces],label='original actual actuator at activation')
 for key in ['Yaw','CourseTerm','BetaTerm']:axs[1].plot(t,[q[key] for q in traces],label=key)
 axs[1].plot(t,[q['Actual']['ChiDot'] for q in traces],label='actual course rate chi-dot')
 axs[2].plot(t,[math.degrees(q['Forces']['SteeringBefore']) for q in traces],label='actual steering');axs[2].plot(t,[math.degrees(q['Action']['SteeringRadians']) for q in traces],label='requested steering')
 for ax in axs:ax.axvline(4.8,color='red',ls=':',lw=1);ax.axvline(6.2,color='red',ls='--',lw=1);ax.legend(fontsize=8,ncol=3)
 axs[0].set_ylabel('rad/s²');axs[1].set_ylabel('rad/s');axs[2].set_ylabel('deg');axs[-1].set_xlabel('original observation / command time [s]');fig.tight_layout();fig.savefig(out/'first-cause.png',dpi=160);plt.close(fig)
 if a['native']:
  name=a['native'][0]['label'];run=read(R/a['native'][0]['source']);ss=run['Riders'][0]['Samples'];t=[s['Input']['Time'] for s in ss];v=[s['Input']['Rider'] for s in ss]
  fig,axs=plt.subplots(4,1,figsize=(12,10),sharex=True)
  axs[0].plot(t,[q['Speed']*3.6 for q in v],label='native speed');axs[1].plot(t,[s['RequestedDrive'] for s in ss],label='requested gas',alpha=.7);axs[1].plot(t,[s['Input']['Active']['Drive'] for s in ss],label='active gas',alpha=.7)
  axs[2].plot(t,[math.degrees(q['SlideRadians']) for q in v],label='beta');axs[2].plot(t,[math.degrees(s['RequestedSteering']) for s in ss],label='requested steering',alpha=.6);axs[2].plot(t,[math.degrees(s['Input']['Steering']) for s in ss],label='actual steering',alpha=.6)
  axs[3].plot(t,[min(s['Inner'],s['Outer']) for s in ss],label='pose');axs[3].plot(t,[s['Certificate'] for s in ss],label='swept');axs[3].axhline(.5,color='red',ls='--')
  for ax in axs:ax.legend(fontsize=8,ncol=3)
  for ax,label in zip(axs,['km/h','gas [0–1]','angle [deg]','clearance [m]']):ax.set_ylabel(label)
  axs[-1].set_xlabel('actual native time [s]');fig.tight_layout();fig.savefig(out/'native-controls.png',dpi=160);plt.close(fig)
  geometry=read(D/'native-replay.json.gz')['geometry'];fig,ax=plt.subplots(figsize=(11,6))
  for edge in ['Inner','Outer']:
   pts=geometry['Boundaries'][edge];ax.plot([q['X'] for q in pts],[q['Y'] for q in pts],color='#333',lw=1)
  for row in a['native']:
   raw=read(R/row['source'])['Riders'][0]['Samples'];ax.plot([s['Input']['Rider']['Position']['X'] for s in raw],[s['Input']['Rider']['Position']['Y'] for s in raw],lw=.8,label=row['label']+' '+('S3' if row['pass_'] else 'DNF'))
  ax.set(aspect='equal',xlabel='x [m]',ylabel='y [m]',title='Original progressive-b boundaries and actual native paths');ax.legend(fontsize=7);fig.tight_layout();fig.savefig(out/'native-xy.png',dpi=160);plt.close(fig)
def report(a):
 p=[];add=p.append;native=a['native'];held=[q for q in native if q['validation']];development=next((q for q in native if not q['validation']),None)
 add('# Badanie #160 — dynamiczne sterowanie β, yaw i prędkością\n')
 add(f"**Werdykt: {a['verdict']}.** Baza: `{a['base']}`. Eksperyment PROVISIONAL, domyślnie OFF; nowa gałąź i Draft PR, bez merge. Prognozy, certyfikaty i rzeczywiste biegi są raportowane osobno.\n")
 add('## Cztery odpowiedzi\n')
 if development:
  first=development['six_bends'][0];add(f"1. **Pierwszy łuk:** status natywny {first['status']}, czas {number(first['duration_s'])} s wobec {number(development['pair']['baseline_first_bend_s'])} s w identycznej bazie (około 24,9% krócej), Vmin {number(first['minimum_kph'])} km/h. Dokładna prognoza #159 przy 12 m/s nadal wypada w 8,8 s; dynamiczna prognoza 12 m/s kończy pełny dystans w 86,4 s z βmax 2,00°.\n")
 add(f"2. **Pełne S3: nie uzyskano nowego ukończenia.** Nominalny v5 zakończył się technicznym DNF przy 67,0 s, po dwóch okrążeniach i pięciu łukach. Nowe światy {len(native)}, ukończenia {sum(q['pass_'] for q in native)}, odłożone {len(held)}, DNF odłożonych {sum(not q['pass_'] for q in held)}. Mediana ukończeń odłożonych {number(a['median_finish_s'])} s. PASS wymaga co najmniej pięciu różnych ukończeń i przewagi nad identyczną bazą. Pojedyncza prognoza 78,2 s ani zielone CI nie spełniają tego warunku.\n")
 add('3. **Składniki:** najmocniejszy dowód dotyczy zastąpienia chwilowej inwersji rzeczywistą odpowiedzią opóźnionego układu skręt–gaz. Ablacja tego kroku narusza obrys przy 15,4 s. Wyłączenie β feed-forward i skrócenie horyzontu do reakcji + jednego review nadal kończą prognozy 12 m/s, więc ich konieczność nie została wykazana. Dłuższy preview zmniejsza szczyt prędkości w tym teście.\n')
 add('4. **Potencjał:** pozostaje istotny zapas do punktów lokalnej równowagi #159 (57,6 km/h w ciasnej części i 72 km/h w środku) i lokalnego przyspieszania na prostej. To propozycje równowagi i lokalne wyniki, bez dowodu osiągalności całego szybszego biegu. W natywnym prefiksie średnie wykorzystanie sił przedniej i tylnej opony wyniosło 25,1% i 31,8%, a średni aktywny gaz 11,7%. Te średnie nie są miarą bezpośrednio dostępnego przyrostu prędkości: ograniczenia momentu yaw, sprzężenia, przejścia i bezpieczeństwo mogą wiązać wcześniej. Nowa polityka rezerwuje 50% skalarnego budżetu siły normalnej na etapie propozycji; certyfikat nadal używa pełnej oryginalnej fizyki i twardych ograniczeń. Nie wyznaczono globalnego optimum silnika/opon.\n')
 add('## Pierwsza przyczyna i łańcuch utraty kontroli\n')
 add('Odtworzono **wszystkie bity stanów, kolejkę, komendy i wszystkie gęste punkty** `rest-speed12`. Ślad porównuje odpowiedzi w tym samym przewidzianym stanie aktywacji +0,24 s. `Control158.Response` tworzy `new TwoContactBikeState(proposedSteering)`, podczas gdy oryginalny kontakt zaczyna od faktycznego skrętu i używa średniej kąta przed/po zmianie. Nawet gdy docelowy kąt mieści się w limicie szybkości, moment w pierwszym kroku jest inny. Śladowe błędy kwantyzacji występują już na prostej; pierwsza duża rozbieżność wejścia w łuk (|αzad| > 0,1 i błąd > 0,1 rad/s²) przypada na komendę 4,8 s.\n')
 traces=[x['Trace'] for x in read(D/'forecasts/exact-rest-speed12.json.gz')['Actions']];selected=[q for q in traces if any(abs(q['Time']-t)<1e-7 for t in [4.8,5,6,6.2,6.6,7,7.2,7.6,8.2])]
 add(table(['Komenda [s]','β aktywacji [°]','α zad.','α założone','α fizyczne','yaw r','χdot','skręt żądany [°]'],[[number(q['Time'],1),number(math.degrees(q['Beta']),2),number(q['DesiredAlpha']),number(q['Imagined']['YawAcceleration']),number(q['Actual']['YawAcceleration']),number(q['Yaw']),number(q['Actual']['ChiDot']),number(math.degrees(q['Action']['SteeringRadians']),2)] for q in selected]))
 add('W 4,8 s α zadane ≈0,573 rad/s², a fizyczne ≈0,287. W 6,2 s żądane α≈+0,539, lecz rzeczywiste ≈−0,485; w 6,6 s żądanie ≈−0,580 daje ≈+2,673. Występują też nieliniowe i niemonotoniczne odpowiedzi przy dużych skrętach, na których bisekcja #158 nie daje gwarancji inwersji. Gaz chwilowej inwersji oscyluje między 0 i 1, zmieniając dostępny moment yaw przez sprzężone siły tylnej opony. W 7,0 s pojawia się żądanie +35°; aktuator i pending nie mogą go odwołać natychmiast. θ obraca się szybciej niż χ, więc β rośnie. Późniejsze tłumienie β i korekta powrotu na linię wzmacniają przeciwne żądania, zamiast usunąć istniejący pęd i kolejkę. Przecięcie obrysu następuje w 8,8 s.\n')
 add('Znaki bazowej krzywizny i skrętu na wejściu są poprawne. Problemem nie jest brak pending w #158: `ActivationState` już przewiduje cały nieodwołalny prefiks. Problemem jest dalsza ocena kandydatów jak osiągniętych kątów i chwilowego gazu oraz utożsamianie celu yaw z kierunkiem ruchu bez przewidzenia rzeczywistego rozwoju β. Nie wykazano, że samo osłabienie tłumienia β usuwa tę przyczynę.\n')
 add('![Łańcuch pierwszej przyczyny](plots/first-cause.png)\n')
 add('## Algorytm i granice jego znaczenia\n')
 add('`β = wrap(θ−χ)`, `χ = atan2(vy,vx)`, `χdot = cross(v,F)/(m |v|²)`, `κXY = cross(v,a)/|v|³`. Yaw r jest prędkością orientacji motocykla; `βdot = r−χdot`. Telemetria przechowuje wszystkie te wielkości osobno.\n')
 add('Feed-forward β i kierownicy pochodzi z numerycznego rozwiązania trzech reszt **oryginalnej** funkcji kontaktów: wzdłużnej siły, normalnej siły wymaganej przez V²κ oraz momentu yaw. Nie ma kopii prawa opon ani nowego integratora. Jest to lokalna propozycja, a nie dowód stabilności; faktyczny wał, sprzęgło, koło, ich energię i aktualny gaz rozstrzyga oryginalny predyktor. Gdy reszta punktu przekracza 0,05 w skalowanych jednostkach, β feed-forward nie jest uznawane za znalezioną równowagę.\n')
 add('Każda propozycja dynamiczna zaczyna od bieżącej obserwacji i **całej** kolejki. Nowa komenda aktywuje się dokładnie po 0,24 s, bez podwójnego dodawania opóźnienia. Horyzont to reakcja + dwa review + czas wykonania zmiany skrętu wynikający z oryginalnego limitu 90°/s, ograniczony interfejsem predyktora do 0,9 s. Przyszły odczyt geometrii pochodzi z rzeczywistej prognozowanej pozycji przy kandydacie gazu i skrętu. To nie stałe przesunięcie w metrach.\n')
 add('Profil propozycji wynika z maksymalnej krzywizny aktualnej linii przez pełny następny manewr i jego kontynuację oraz oryginalnego budżetu sił i wykonalności lokalnej równowagi. To konserwatywna obwiednia: na symetrycznym torze bywa prawie płaska, a przy wyjściu zmienia się z celem. Nie jest globalnym optimum ani kompletnym rozwiązaniem problemu hamowania — bezpieczną osiągalność od aktualnego stanu sprawdzają dopiero pełne kontynuacje. Nie ma osobnych limitów prosta/łuk. Szersza linia 6 m została zbadana, ale odrzucona za β45 podczas przejścia; nie przypisujemy jej korzyści z samego większego promienia.\n')
 add('Lokalne ograniczone strzelanie gaz–skręt wykorzystuje do trzech iteracji 2×2 z rzeczywistym predyktorem; reszty yaw i prędkości służą wyłącznie propozycji. Wybór planu wykonuje odziedziczony planner z `RankPolicies=true`: najwyżej trzy korzenie, co piąte review ograniczone dodatkowe próby, **rzeczywisty czas do wspólnego celu**, minimum 0,02 s korzyści przed kolejnym pełnym drzewem, legalna kontynuacja i niezależna recertyfikacja. Nie ma nagrody za Vmax, β=0 ani pełny gaz.\n')
 add('Dla perturbowanych stanów rezerw używany jest feedback do własnego świeżo wygenerowanego planu, z lokalną pochodną momentu oryginalnego, rzeczywistego aktuatora. Taki feedback jest tylko propozycją: każda jego kontynuacja jest fizycznie repropagowana. Własny zatrzymany plan jest ponownie certyfikowany; nie ma importu starej taśmy #158 ani automatycznego fallbacku ON do starego kontrolera. OFF bezpośrednio deleguje do niezmienionego `Planner158`. `Planner160.Generated.cs` zmienia wyłącznie nazwy i trzy haki propozycji względem #158; `Runtime158`, 13 węzłów, 9 pełnych rezerw i niezależny preflight pozostają oryginalne.\n')
 add('## Wszystkie prognozy i ablacje\n')
 add(table(['Próba','Cel osiągnięty','Legalna','Koniec [s]','I łuk [s]','βmax [°]','swept min [m]','CPU [s]','Powód'],[[q['Label'],q['Reached'],q['Legal'],number(q['EndTime'],1),number(q['first_bend_duration_s']),number(q['Safety']['MaximumBetaDegrees'],2),number(q['Safety']['SweepLowerBoundMeters']),number(q['CpuSeconds'],2),q['Reason'].replace('|','/').split('\r')[0]] for q in a['forecasts']]))
 add('Ablacje v2 zmieniają po jednym przełączniku względem dynamic12-v2. „Actuator=false” wraca do chwilowej inwersji gaz–skręt, zachowując β feed-forward i odczyt przyszłej geometrii. β=false usuwa tylko fizyczny cel β. Preview=false skraca horyzont do reakcji + jednego review; nie usuwa nieodwołalnego prefiksu. To lokalna identyfikacja mechanizmu, bez deklaracji odporności ablowanych polityk. Pierwsze v1/v2 i późniejsze v3/v5 są wersjami rozwojowymi, nie pojedynczym czystym porównaniem.\n')
 add('![Prognozy diagnostyczne](plots/diagnostic-controls.png)\n')
 add('## Certyfikaty i bramki\n')
 add(table(['Próba','Pełne 13/9 + independent','CPU [s]','Węzły','Rezerwy'],[[q['label'],q['pass_'],number(q['cpu_s'],2),q['nodes'],q['reserves']] for q in a['certificates']]))
 add('A: odtworzenie #159 i całego OFF/base10 dokładne, łącznie z wszystkimi punktami;  B: stabilna szybsza prognoza pierwszego łuku przy 12 m/s; C: pełna adaptacyjna prognoza 78,2 s, swept 3,699 m; D: pełne certyfikaty kandydatów v3–v5. Szósty, ostatni probe odtwarza techniczny błąd z natywnego końca, bez własnego zachowanego portfolio. V6 zawiera późniejszą poprawkę numeryczną i nie uzyskał nowego pełnego certyfikatu — limit sześciu probe pozostał zamknięty. E i F rozstrzygają wyłącznie poniższe światy natywne. Certyfikat w wybranym stanie nie gwarantuje braku przyszłego ABSTAIN.\n')
 add('## Światy natywne i pary #158\n')
 add(table(['Próba','Status','Okrążenia','Czas S3 [s]','Baza [s]','Δ [s]','Obrys [m]','Swept [m]','βmax [°]','CPU [s]'],[[q['label'],'S3' if q['pass_'] else 'DNF',q['completed_laps'],number(q['finish_s']),number(q['pair']['baseline_finish_s']),number(q['pair']['delta_s']),number(q['minimum_pose_m']),number(q['minimum_swept_m']),number(q['maximum_beta_deg'],2),number(q['cpu_process_s'],2)] for q in native]))
 add('Pary wymagają równości pełnego stanu startowego (w tym wału, koła, aktywnej komendy, pending i review), pierwszej próbki, specyfikacji masy i bezwładności oraz niezmienionych drzew fizyki i geometrii. DNF pozostaje w mianowniku i nie otrzymuje fikcyjnego czasu mety. Mediana i rozrzut obejmują ukończenia odłożone; rozwój jest oddzielny. Warunki są wcześniej ustalonym zestawem final-v6 #158, bez wykorzystania odłożonych wyników do dostrajania.\n')
 for q in native:
  add(f"### {q['label']}: {'S3' if q['pass_'] else 'DNF'}\n")
  add(f"Okrążenia [s]: {', '.join(number(v) for v in q['laps_s']) or 'brak'}. Droga XY: {number(q['distance_xy_m'])} m. Zaakceptowane decyzje: {q['accepted_decisions']}; ABSTAIN: {q['abstain']}; kontakty: {q['contacts']}; odrzucone próby planów: {len(q['rejected_plans'])}. CPU callbacków: suma {number(q['cpu_callbacks']['total'])} s, mediana {number(q['cpu_callbacks']['median'])} s, maksimum {number(q['cpu_callbacks']['maximum'])} s.\n")
  add(table(['Łuk','Status','Wejście [s]','Wejście [km/h]','Vmin [km/h]','Wyjście [km/h]','Czas [s]'],[[b['bend'],b['status'],number(b['entry']['time_s']) if b['entry'] else '—',number(b['entry']['speed_kph']) if b['entry'] else '—',number(b['minimum_kph']),number(b['exit']['speed_kph']) if b['exit'] else '—',number(b['duration_s'])] for b in q['six_bends']]))
  add(table(['Okrążenie / prosta','Obserwowany czas [s]','Vśrednia [km/h]','Vmax [km/h]'],[[f"{s['lap']}/{s['section']}",number(s['observed_s']),number(s['mean_kph']),number(s['maximum_kph'])] for s in q['straights']]))
  if q['failures']:add('Pierwsza odmowa: `'+str(q['failures'][0]['reason'])+'`, t='+number(q['failures'][0]['time_s'])+' s. Pełne stany, odrzucenia i rezerwy w surowej polityce wskazanej w analysis.json.\n')
  add('CPU faz: '+', '.join(f'{k}: {v:.3f} s' for k,v in q['cpu_phases'].items())+'. Nie sumować tego ponownie z CPU callbacków.\n')
 add('![Rzeczywista trajektoria](plots/native-xy.png)\n![Rzeczywiste sterowanie](plots/native-controls.png)\n')
 add('## Rzeczywisty DNF i poprawka v6\n')
 add('Przy 67,0 s motocykl nadal był fizycznie legalny: β≈−0,008°, r≈−0,00144 rad/s, prędkość 50,13 km/h, brak kontaktów. Cały bieg ma minimum obrysu 0,789 m i swept 0,719 m; maksimum β 3,154°. Do motocykla trafiło 335 legalnych, świeżo certyfikowanych komend. Nielegalny kandydat nie został wykonany. To **techniczne DNF planowania**, nie naruszenie faktycznej trajektorii ani wyczerpanie CPU. Licznik ABSTAIN wynosi 0, ponieważ ArgumentException opuścił callback przed zapisaniem wiersza odmowy; natywny harness zachował wyjątek w Outcome i zakończył bieg.\n')
 add('Zmiana wspólnego celu przy wejściu w szósty łuk wymagała już rezerwy do 988,336 m, czyli 32 m za metą. W poprzednim review cel wynosił 828,947 m, a safetyGoal 956,336 m. Pełny natywny stan przy 67 s ma offset 0,679 m i składową prędkości do wewnątrz około 1,413 m/s, mimo β bliskiego zeru. To pokazuje, dlaczego sam mały β nie jest bezpieczeństwem linii.\n')
 add('Szósty probe uruchomiony z dokładnego stanu natywnego, lecz ze świeżym plannerem bez zachowanego portfolio, odtworzył ten sam wyjątek. W prognozowanej rezerwie przy t=78,0 s, referencji 976,403 m (już za metą, przed obowiązkowym końcem rezerwy) skończona różnica żądała 0,6258652 rad, tj. 35,859°, ponad fizyczne 35° = 0,61086524 rad. Punkt próbny powstał jako maksymalny dopuszczalny iterat + 0,015 rad. Oryginalna walidacja słusznie go odrzuciła; błąd generatora zamienił odrzucenie kandydatu w przerwanie całej decyzji. Surowe LastProbe i pełny stack są w certificates/terminal-cause-v5.json.gz. To reprodukcja mechanizmu, nie odtworzenie utraconego wewnętrznego portfolio natywnego.\n')
 add('V6 stosuje jednostronną różnicę skierowaną do wnętrza dopuszczalnego zakresu i rzeczywisty mianownik kroku. Test regresji używa zapisanego stanu błędu. Nominalna prognoza v6 nadal kończy trzy okrążenia w 78,2 s, ale nie jest nowym biegiem. Kontynuacja v6 z końca DNF, z pełną kolejką i bez resetu jej fizyki, nie osiąga safetyGoal: przy 78,4 s i 981,752 m narusza obrys (swept −0,666 m, βmax 49,20°). Nie ma już wyjątku, lecz istnieje nielegalny proponowany manewr. To nie dowód niemożliwości innej kontynuacji.\n')
